-- Script idempotent bổ sung MỌI cột còn thiếu cho tất cả bảng.
-- Sinh tự động từ schema local (khớp entity). Chỉ ADD nếu cột chưa có → chạy lại nhiều lần vô hại.
-- KHÔNG sửa/xoá cột nào đang có. Chạy: mysql -u root -p <DB_SERVER> < scripts/fix-all-missing-columns.sql

-- ===== alumni_batch_responses =====
SET @t := (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='alumni_batch_responses');
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='alumni_batch_responses' AND COLUMN_NAME='batch_id');
SET @s := IF(@t=1 AND @c=0, "ALTER TABLE \`alumni_batch_responses\` ADD COLUMN \`batch_id\` bigint unsigned NOT NULL DEFAULT 0", 'SELECT 1');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
